export interface ConnectorConfig {
  /** Stripe webhook signing secret used to verify the Stripe-Signature header. */
  stripeWebhookSecret: string
  /** HubSpot private app access token for API authentication. */
  hubspotAccessToken: string
  /** Optional fetch implementation for testing or custom HTTP behavior. */
  fetch?: typeof fetch
}

export interface StripeCheckoutSessionCompletedPayload {
  id: string
  customer: {
    email: string
  }
  client_reference_id?: string
}

export interface HubSpotContactResult {
  vid: number
  isNew: boolean
}

export async function handle(
  payload: StripeCheckoutSessionCompletedPayload,
  config: ConnectorConfig
): Promise<HubSpotContactResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.id) {
    throw new Error('Missing required field: id (Stripe session id)')
  }
  if (!payload.customer?.email) {
    throw new Error('Missing required field: customer.email')
  }

  const email = payload.customer.email
  const url = `https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/${encodeURIComponent(email)}`

  const properties: Array<{ property: string; value: string }> = [
    { property: 'email', value: email }
  ]

  if (payload.client_reference_id) {
    properties.push({ property: 'client_reference_id', value: payload.client_reference_id })
  }

  const body = JSON.stringify({ properties })

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.hubspotAccessToken}`,
      'Content-Type': 'application/json',
      'Idempotency-Key': payload.id
    },
    body
  })

  if (!response.ok) {
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const result = (await response.json()) as HubSpotContactResult
  return result
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, StripeCheckoutSessionCompletedPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      stripeWebhookSecret: 'whsec_test',
      hubspotAccessToken: 'pat_test',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeCheckoutSessionCompletedPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.vid).toBe(3234574)
    expect(result.isNew).toBe(false)
  })
})

describe('handle', () => {
  it('maps fields correctly and sends expected request', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/customer%40example.com'
        ? jsonResponse({ vid: 123, isNew: true }, 201)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_test_123',
      customer: { email: 'customer@example.com' },
      client_reference_id: 'order_456'
    }

    const config: ConnectorConfig = {
      stripeWebhookSecret: 'whsec_test',
      hubspotAccessToken: 'pat_test',
      fetch
    }

    const result = await handle(payload, config)

    expect(result).toEqual({ vid: 123, isNew: true })
    expect(calls).toHaveLength(1)

    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/customer%40example.com')
    expect(call.headers.get('authorization')).toBe('Bearer pat_test')
    expect(call.headers.get('idempotency-key')).toBe('cs_test_123')
    expect(call.json).toEqual({
      properties: [
        { property: 'email', value: 'customer@example.com' },
        { property: 'client_reference_id', value: 'order_456' }
      ]
    })
  })

  it('omits client_reference_id when not present', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/test%40example.com'
        ? jsonResponse({ vid: 456, isNew: false })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_test_456',
      customer: { email: 'test@example.com' }
    }

    const config: ConnectorConfig = {
      stripeWebhookSecret: 'whsec_test',
      hubspotAccessToken: 'pat_test',
      fetch
    }

    await handle(payload, config)

    expect(calls[0].json).toEqual({
      properties: [{ property: 'email', value: 'test@example.com' }]
    })
  })

  it('throws descriptive error when id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { customer: { email: 'test@example.com' } } as unknown as StripeCheckoutSessionCompletedPayload
    const config: ConnectorConfig = { stripeWebhookSecret: 'whsec_test', hubspotAccessToken: 'pat_test', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: id')
  })

  it('throws descriptive error when customer.email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { id: 'cs_test_789' } as unknown as StripeCheckoutSessionCompletedPayload
    const config: ConnectorConfig = { stripeWebhookSecret: 'whsec_test', hubspotAccessToken: 'pat_test', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: customer.email')
  })

  it('throws on non-2xx response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ message: 'Unauthorized' }, 401))

    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_test_999',
      customer: { email: 'fail@example.com' }
    }

    const config: ConnectorConfig = {
      stripeWebhookSecret: 'whsec_test',
      hubspotAccessToken: 'invalid_token',
      fetch
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'HubSpot API error: 401 Unauthorized for POST https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/fail%40example.com'
    )
    expect(calls).toHaveLength(1)
  })

  it('uses injected fetch implementation', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ vid: 999, isNew: true }, 201))

    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_test_injected',
      customer: { email: 'injected@example.com' }
    }

    const config: ConnectorConfig = {
      stripeWebhookSecret: 'whsec_test',
      hubspotAccessToken: 'pat_test',
      fetch
    }

    const result = await handle(payload, config)
    expect(result.vid).toBe(999)
    expect(calls).toHaveLength(1)
  })
})

